function load(rel){ const f = path.join(root, rel); const raw = fs.readFileSync(f, 'utf8'); return { f, rel, crlf: raw.includes('\r\n'), text: raw.replace(/\r\n/g, '\n') }; }
function save(o){ fs.writeFileSync(o.f, o.crlf ? o.text.replace(/\n/g, '\r\n') : o.text); }
const fxPath = path.join(root, 'www', 'fx.js');
if (!fs.existsSync(fxPath)){ console.log('Apply the masks v2 patch first (tools/apply-masks-v2.js): www/fx.js is missing.'); process.exit(1); }
const fxNow = fs.readFileSync(fxPath, 'utf8');
if (fxNow.includes('masks-fx2+shapes')){ console.log('Already applied (www/fx.js has the shapes code). Nothing to do.'); process.exit(0); }
if (!fxNow.includes('masks-fx2')){ console.log('Apply the masks v2 patch first (tools/apply-masks-v2.js): www/fx.js is not the masks v2 version.'); process.exit(1); }
const problems = [], notes = [], files = {};
Object.keys(EDITS).forEach(rel => {
  if (!fs.existsSync(path.join(root, rel))){ if (EDITS[rel].every(e => e.op === 'opt')) return; problems.push(rel + ' does not exist'); return; }
  const o = files[rel] = load(rel);
  EDITS[rel].forEach(e => {
    const n = o.text.split(e.find).length - 1;
    if (e.op === 'opt'){ if (n === 1) o.text = o.text.replace(e.find, () => e.replace); else notes.push(e.label + ': not changed (found ' + n + ' times in ' + path.basename(rel) + '); it only affects the version list on the Home screen'); return; }
    if (n !== 1){ problems.push(e.label + ': found ' + n + ' times (need exactly 1) in ' + path.basename(rel)); return; }
    o.text = o.text.replace(e.find, () => e.replace);
  });
});
if (problems.length){
  console.log('NOTHING WAS CHANGED. These spots did not match your files:\n  - ' + problems.join('\n  - '));
  console.log('\nSend me that list (and the file names) and I will adjust.');
  process.exit(1);
}
Object.keys(files).forEach(rel => save(files[rel]));
fs.mkdirSync(path.join(root, 'tests'), { recursive: true });
fs.writeFileSync(path.join(root, 'tests', 'shapes.test.js'), B.test);
try {   // add the new test to "npm test" when it lists its tests one by one
  const pj = path.join(root, 'package.json'), pkg = JSON.parse(fs.readFileSync(pj, 'utf8'));
  if (pkg.scripts && pkg.scripts.test && !/tests[\/\\]\*|shapes\.test\.js/.test(pkg.scripts.test)){ pkg.scripts.test += ' && node tests/shapes.test.js'; fs.writeFileSync(pj, JSON.stringify(pkg, null, 2) + '\n'); notes.push('Added tests/shapes.test.js to "npm test".'); }
} catch (e) { notes.push('Could not edit package.json: add  node tests/shapes.test.js  to your test script yourself.'); }
console.log('Done. Changed ' + Object.keys(files).length + ' files and added tests/shapes.test.js.' + (notes.length ? '\n' + notes.map(x => '  note: ' + x).join('\n') : '') + '\nNow run:  npm test');